#include <cmath>
#include <vector>
#include <random>
#include <algorithm>
struct Pix {int x,y; float a,b;};
struct Kernel {std::vector<Pix> px;float len,dep,theta;};
std::vector<Kernel> ks;
std::mt19937 rng(284);
extern "C" void addkernel(float* a,int w,int h,float len,float dep,float theta){Kernel k;k.len=len;k.dep=dep;k.theta=theta;for(int y=0;y<h;y++)for(int x=0;x<w;x++){float v=a[y*w+x];if(v>.015)k.px.push_back({x-w/2,y-h/2,v,v*v});}ks.push_back(k);}
extern "C" float search(float* c,float* t,float* pal,float* weights,int n,int trials,float* out){
 std::discrete_distribution<int> dist(weights,weights+n*n);std::uniform_int_distribution<int> kd(0,ks.size()-1);float best=-1e30;int bx=0,by=0,bk=0,bc=0;
 auto eval=[&](int x,int y,int ki){auto &k=ks[ki];float D[3]={},B=0,E=0;int good=0;
 for(auto &p:k.px){int xx=x+p.x,yy=y+p.y;if(xx<2||xx>=n-2||yy<2||yy>=n-2)continue;int i=(yy*n+xx)*3;float aa=p.a;B+=p.b;good++;for(int j=0;j<3;j++){float cc=c[i+j],tt=t[i+j];D[j]+=aa*tt-(aa-p.b)*cc;E+=-2*aa*tt*cc+(2*aa-p.b)*cc*cc;}}
 if(B<.1||good<k.px.size()*.75)return;
 float score=-1e30;int color=0;
 for(int z=0;z<16;z++){float v=E;for(int j=0;j<3;j++)v+=2*pal[z*3+j]*D[j]-B*pal[z*3+j]*pal[z*3+j];if(v>score){score=v;color=z;}}
 if(score>best){best=score;bx=x;by=y;bk=ki;bc=color;}
 };
 for(int i=0;i<trials;i++){int p=dist(rng);eval(p%n,p/n,kd(rng));}
 for(int r=0;r<3;r++){int x=bx,y=by;for(int k=0;k<(int)ks.size();k++)eval(x,y,k);for(int dy=-3;dy<=3;dy++)for(int dx=-3;dx<=3;dx++)eval(x+dx,y+dy,bk);}
 out[0]=bx;out[1]=by;out[2]=bk;out[3]=bc;return best;
}
