lib=ctypes.CDLL(OUT+'/planner.so');ptr=np.ctypeslib.ndpointer(dtype=np.float32,flags='C_CONTIGUOUS')
lib.addkernel.argtypes=[ptr,ctypes.c_int,ctypes.c_int,ctypes.c_float,ctypes.c_float,ctypes.c_float]
lib.search.argtypes=[ptr,ptr,ptr,ptr,ctypes.c_int,ctypes.c_int,ptr];lib.search.restype=ctypes.c_float
