 wx,wy=sheets['main'].mm_to_world(x,y);mp.sample([wx,wy,.02-dep*.001],R)
for dep in [1.5,2.2,3.2,4.5,6.0]:
 for length in [2.,5.,9.,15.,24.,38.,60.]:
  mp.reset();w=inst['wells']['wells'][7];mp.sample([*w['center_xy'],.025],R)
  # Start and finish dwelling reflect the settled robot motion.
  for _ in range(25):mpsample(113-length/2,113,dep)
  for x in np.linspace(113-length/2,113+length/2,max(2,int(length/.4))):mpsample(x,113,dep)
  for _ in range(15):mpsample(113+length/2,113,dep)
  mpsample(113+length/2,113,-3)
  a=cv2.resize(mp.display_ink(),(N,N),interpolation=cv2.INTER_AREA)
  for angle in np.arange(0,180,15):
   theta=float(np.deg2rad(angle)); rad=int(np.ceil((length/2+9)*SCALE));size=rad*2+1
   mat=cv2.getRotationMatrix2D((113*SCALE-.5,113*SCALE-.5),-float(angle),1)
   mat[:,2]+=rad-np.array([113*SCALE-.5,113*SCALE-.5])
   ar=cv2.warpAffine(a,mat,(size,size)).astype(np.float32)
   lib.addkernel(ar,size,size,length,dep,theta);kernels.append((length,dep,theta))
print('kernels',len(kernels),flush=True)
target=cv2.cvtColor(cv2.imread('/app/target.png'),cv2.COLOR_BGR2RGB).astype(np.float32)/255
# The score sees a 1 mm blur. A little less here retains contrast in small features.
t=cv2.resize(cv2.GaussianBlur(target,(0,0),3.0),(N,N),interpolation=cv2.INTER_AREA)
tl=cv2.cvtColor(t,cv2.COLOR_RGB2LAB);pal=cv2.cvtColor(palette[None],cv2.COLOR_RGB2LAB)[0]
s=Session(instance=INST,render=False);p=s.primitives();s.record_start();beg=time.time();commands=[]
def move(pos,speed=.15,settle=0):return p['move_tip'](pos,speed=speed,settle=settle)
def xy(X,Y,z):return [*s.geo.mm_to_world(X,Y),z]
def dip(col):
 pos=s.tip_pose()[0];move([pos[0],pos[1],.052],.12,1)
 w=s.wells()[col];move([*w['center_xy'],.052],.24,1);move([*w['center_xy'],.025],.10,3);move([*w['center_xy'],.052],.14,1)
def stroke(x,y,length,dep,theta,col):
 dx=length/2*np.cos(theta);dy=length/2*np.sin(theta);x0,y0=x-dx,y-dy;x1,y1=x+dx,y+dy
 dip(col);move(xy(x0,y0,.035),.24,3);move(xy(x0,y0,.02-dep*.001),.07,4)
 move(xy(x1,y1,.02-dep*.001),.04,3);move(xy(x1,y1,.035),.08,3)
 commands.append([float(v) for v in [x,y,length,dep,theta,col]])
def save(tag):
 a=np.asarray(s._recording,np.float32);s.save_trajectory(a,OUT+'/trajectory'+tag+'.npz');Image.fromarray(s.canvas()).save(OUT+'/canvas'+tag+'.png');json.dump(commands,open(OUT+'/commands'+tag+'.json','w'))
# Opaque overlapping serpentine base coat: one continuous contact.
dip(7);move(xy(3,3,.035),.24,3);move(xy(3,3,.014),.07,4)
for j,y in enumerate(np.arange(3,226,6.0)):
 x=224 if j%2==0 else 3
 move(xy(x,y,.014),.07,2)
 if y+6<226:move(xy(x,y+6,.014),.045,1)
pos=s.tip_pose()[0];move([pos[0],pos[1],.04],.1,3)
print('base',s.n_steps,time.time()-beg,flush=True)
for i in range(680):
 c=cv2.resize(s.canvas().astype(np.float32)/255,(N,N),interpolation=cv2.INTER_AREA)
 c=cv2.GaussianBlur(c,(0,0),.65)
 cl=cv2.cvtColor(c,cv2.COLOR_RGB2LAB)
 err=np.sum((cl-tl)**2,2);weights=cv2.GaussianBlur(err,(0,0),2).astype(np.float32);weights[:8]=0;weights[-8:]=0;weights[:,:8]=0;weights[:,-8:]=0
 out=np.zeros(4,np.float32);gain=lib.search(cl,tl,pal,weights,N,9000,out)
 x,y,k,col=map(int,out);length,dep,theta=kernels[k]
 stroke((x+.5)/SCALE,(y+.5)/SCALE,length,dep,theta,col)
 if (i+1)%20==0:
  print('stroke',i+1,'steps',s.n_steps,'secs',round(time.time()-beg,1),'gain',round(gain),'proxy_de',round(float(np.sqrt(err)[10:-10,10:-10].mean()),2),flush=True)
 if (i+1)%100==0:save('_'+str(i+1))
 if s.n_steps>69000:break
save('');print('SCORE',s.score(),flush=True)
